$(
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
  Van der Waerden's theorem
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
$)

  $( Introduce new constant symbols. $)
  $c AP $. $( Arithmetic progression $)
  $c MonoAP $. $( Monochromatic arithmetic progression $)
  $c PolyAP $. $( Polychromatic arithmetic progression $)

  $( The arithmetic progression function. $)
  cvdwa $a class AP $.

  $( The monochromatic arithmetic progression predicate. $)
  cvdwm $a class MonoAP $.

  $( The polychromatic arithmetic progression predicate. $)
  cvdwp $a class PolyAP $.

  ${
    $d a c d f i k m $.
    $( Define the arithmetic progression function, which takes as input a
       length ` k ` , a start point ` a ` , and a step ` d ` and outputs the
       set of points in this progression.  (Contributed by Mario Carneiro,
       18-Aug-2014.) $)
    df-vdwap $a |- AP = ( k e. NN0 |-> ( a e. NN , d e. NN |->
      ran ( m e. ( 0 ... ( k - 1 ) ) |-> ( a + ( m x. d ) ) ) ) ) $.

    $( Define the "contains a monochromatic AP" predicate.  (Contributed by
       Mario Carneiro, 18-Aug-2014.) $)
    df-vdwmc $a |- MonoAP = { <. k , f >. |
      E. c ( ran ( AP ` k ) i^i ~P ( `' f " { c } ) ) =/= (/) } $.

    $( Define the "contains a polychromatic collection of APs" predicate.  See
       ~ vdwpc for more information.  (Contributed by Mario Carneiro,
       18-Aug-2014.) $)
    df-vdwpc $a |- PolyAP = { <. <. m , k >. , f >. | E. a e. NN
      E. d e. ( NN ^m ( 1 ... m ) ) ( A. i e. ( 1 ... m )
      ( ( a + ( d ` i ) ) ( AP ` k ) ( d ` i ) ) C_
        ( `' f " { ( f ` ( a + ( d ` i ) ) ) } ) /\
      ( # ` ran ( i e. ( 1 ... m ) |-> ( f ` ( a + ( d ` i ) ) ) ) ) = m ) } $.
  $}

